// The structural comparison behind src/oracle.ts: both sides' prop types reduced to one shape, and one verdict per
// pair. Pure: nothing here talks to the checker.

/** A type reduced to what both sides can state: kind, literal value, members, fields, parameters. `alias` is the
 * checker's name for it (an alias, or the interface that declares it), which Caliper may print instead. */
export type Norm = (
  | { k: 'prim'; name: string }
  | { k: 'lit'; value: string }
  | { k: 'union'; members: Norm[] }
  | { k: 'intersection'; members: Norm[] }
  | { k: 'array'; element: Norm }
  | { k: 'tuple'; elements: Norm[] }
  | { k: 'function'; params: { optional: boolean; rest: boolean; type: Norm }[]; returns: Norm }
  | { k: 'object'; fields: string[]; index: boolean }
  | { k: 'name'; name: string }
  | { k: 'param'; name: string; fallback?: Norm; constraint?: Norm }
  | { k: 'opaque' }
  | { k: 'error' }
) & { alias?: string }

export type Verdict = 'identical' | 'spelled' | 'less precise' | 'wrong' | 'checker any/error'

export const MAX_DEPTH = 3
export const VERDICTS: Verdict[] = ['identical', 'spelled', 'less precise', 'wrong', 'checker any/error']
const RANK: Verdict[] = ['identical', 'spelled', 'less precise', 'wrong']

/** A type name without `React.` or a namespace qualifier. */
export const bareName = (name: string) => name.replace(/^.*\./, '')
export const prim = (name: string): Norm => ({ k: 'prim', name })

const TERMINALS: Record<string, string> = {
  reactNode: 'ReactNode',
  cssProperties: 'CSSProperties',
  elementType: 'ElementType',
  htmlAttributes: 'HTMLAttributes',
  ref: 'Ref',
  sxProps: 'SxProps',
}
const PRIMITIVES = new Set(['string', 'number', 'boolean', 'null', 'undefined', 'any', 'unknown', 'never', 'void'])
const LITERALS = new Set(['stringLiteral', 'numberLiteral', 'boolLiteral'])

/** Caliper's canonical `PropType` JSON, normalized. */
export function caliperNorm(t: any, depth = 0): Norm {
  if (!t || depth > MAX_DEPTH) return { k: 'opaque' }
  if (PRIMITIVES.has(t.kind)) return prim(t.kind)
  if (LITERALS.has(t.kind)) return { k: 'lit', value: String(t.value) }
  const inner = (m: any) => caliperNorm(m, depth + 1)
  switch (t.kind) {
    case 'literalUnion': {
      return { k: 'union', members: t.members.map((m: string) => ({ k: 'lit', value: m })) }
    }
    case 'union': {
      return { k: 'union', members: t.members.map((m: any) => inner(m)) }
    }
    case 'intersection': {
      const parts: Norm[] = t.members.map((m: any) => inner(m))
      const meaningful = parts.filter((m) => !(m.k === 'object' && m.fields.length === 0))
      return meaningful.length === 1 ? meaningful[0] : { k: 'intersection', members: parts }
    }
    case 'array': {
      return { k: 'array', element: inner(t.element) }
    }
    case 'tuple': {
      return { k: 'tuple', elements: (t.elements ?? t.members ?? []).map((m: any) => inner(m)) }
    }
    case 'object': {
      return { k: 'object', fields: t.fields.map((field: any) => field.name).toSorted(), index: false }
    }
    case 'function': {
      const params = (t.params ?? []).map((p: any) => ({ optional: false, rest: false, type: inner(p.type) }))
      return { k: 'function', params, returns: inner(t.returnType) }
    }
    case 'named': {
      return { k: 'name', name: bareName(t.name) }
    }
    default: {
      return TERMINALS[t.kind] ? { k: 'name', name: TERMINALS[t.kind] } : { k: 'opaque' }
    }
  }
}

const worst = (vs: Verdict[]): Verdict => vs.reduce((a, b) => (RANK.indexOf(b) > RANK.indexOf(a) ? b : a), 'identical')
const best = (vs: Verdict[]): Verdict => vs.reduce((a, b) => (RANK.indexOf(b) < RANK.indexOf(a) ? b : a), 'wrong')
const isLit = (n: Norm, value?: string) => n.k === 'lit' && (value === undefined || n.value === value)
const isUndefined = (m: Norm) => m.k === 'prim' && m.name === 'undefined'
const WIDENING = new Set(['string', 'number', 'boolean'])

/** Union members without `undefined` (an optional prop's, which both sides treat as optional), flattened, with
 * `true | false` as `boolean`. */
function members(n: Norm, written = false): Norm[] {
  const flat: Norm[] = []
  const push = (m: Norm) => {
    if (m.k === 'union') m.members.forEach(push)
    // An optional generic prop reads `T | (undefined & T)`.
    else if (!isUndefined(m) && !(m.k === 'intersection' && m.members.some(isUndefined))) flat.push(m)
  }
  push(n)
  // `'default' | 'large' | string` is `string` to the checker: a literal that a primitive of its kind in the same
  // union already covers adds nothing, so a union Caliper wrote with it reads the same as one without. Only Caliper's
  // (`written`): the checker's `"blue" | … | (string & {})` keeps its literals, which are what a reader sees. A
  // `true`/`false` literal is boolean's, not string's.
  const has = (name: string) => flat.some((m) => m.k === 'prim' && m.name === name)
  const covered = (m: Norm) =>
    written &&
    m.k === 'lit' &&
    m.value !== 'true' &&
    m.value !== 'false' &&
    (/^-?\d+(\.\d+)?$/.test(m.value) ? has('number') : has('string'))
  const kept = flat.filter((m) => !covered(m))
  if (kept.some((m) => isLit(m, 'true')) && kept.some((m) => isLit(m, 'false'))) {
    return [...kept.filter((m) => !isLit(m, 'true') && !isLit(m, 'false')), prim('boolean')]
  }
  return kept
}

/** Two unions: each checker member covered by one of Caliper's (a missing member makes Caliper's type too narrow),
 * and each of Caliper's matched by one of the checker's (an extra member makes it too wide, unless it widens
 * literals). */
function compareUnions(cm: Norm[], km: Norm[], depth: number): Verdict {
  const kCovered = km.map((m) => best(cm.map((cMember) => compare(cMember, m, depth + 1))))
  const cMatched = cm.map((m) => {
    const verdict = best(km.map((kMember) => compare(m, kMember, depth + 1)))
    const widens =
      m.k === 'prim' &&
      WIDENING.has(m.name) &&
      km.some((kMember) => kMember.k === 'lit' || (kMember.k === 'prim' && kMember.name === m.name))
    return verdict === 'wrong' && widens ? 'less precise' : verdict
  })
  return worst([...kCovered, ...cMatched])
}

function compareFunctions(c: Norm & { k: 'function' }, k: Norm & { k: 'function' }, depth: number): Verdict {
  const verdicts: Verdict[] = [compare(c.returns, k.returns, depth + 1)]
  for (const [i, kp] of k.params.entries()) {
    const cp = c.params[i]
    if (cp === undefined) {
      verdicts.push(kp.optional || kp.rest ? 'less precise' : 'wrong')
    } else {
      verdicts.push(compare(cp.type, kp.type, depth + 1))
      // Caliper's function types record neither marker.
      if (kp.optional || kp.rest) verdicts.push('less precise')
    }
  }
  if (c.params.length > k.params.length) verdicts.push('wrong')
  return worst(verdicts)
}

/** One non-union type against another. */
function compareOne(c: Norm, k: Norm, depth: number): Verdict {
  switch (k.k) {
    case 'prim': {
      return c.k === 'prim' && c.name === k.name ? 'identical' : 'wrong'
    }
    case 'lit': {
      if (c.k === 'lit') return c.value === k.value ? 'identical' : 'wrong'
      return c.k === 'prim' && WIDENING.has(c.name) ? 'less precise' : 'wrong'
    }
    case 'array': {
      return c.k === 'array' ? compare(c.element, k.element, depth + 1) : 'wrong'
    }
    case 'tuple': {
      if (c.k !== 'tuple') return c.k === 'array' ? 'less precise' : 'wrong'
      if (c.elements.length !== k.elements.length) return 'wrong'
      return worst(c.elements.map((e, i) => compare(e, k.elements[i], depth + 1)))
    }
    case 'function': {
      return c.k === 'function' ? compareFunctions(c, k, depth) : 'wrong'
    }
    case 'object': {
      if (c.k !== 'object') return c.k === 'prim' && c.name === 'object' ? 'less precise' : 'wrong'
      const own = new Set(c.fields)
      if (c.fields.some((f) => !k.fields.includes(f))) return 'wrong'
      return k.fields.some((f) => !own.has(f)) || k.index ? 'less precise' : 'identical'
    }
    case 'intersection': {
      if (c.k !== 'intersection') return 'less precise'
      return c.members.length === k.members.length ? 'identical' : 'less precise'
    }
    case 'param': {
      // A type parameter of the component itself, which Caliper replaced with an instantiation: its default, as a bare
      // `AccordionProps` means `AccordionProps<false>`, or its constraint. That is one instance of the parameter,
      // looser or narrower than the parameter itself, and not another type; a type that is neither instance is.
      // `c` may be one member of a union Caliper wrote out (`string` of `string | number`), so it must fit one member of
      // an instance, not all of them.
      const instances = [k.fallback, k.constraint].filter((i): i is Norm => i !== undefined).flatMap((i) => members(i))
      // A parameter with neither (a generic component cast over `forwardRef`, whose props interface declares the
      // default) leaves the checker no instance to hold Caliper's to: any one it picked is one value of the parameter.
      if (instances.length === 0) return 'less precise'
      return instances.some((i) => compare(c, i, depth + 1) !== 'wrong') ? 'less precise' : 'wrong'
    }
    default: {
      return 'wrong'
    }
  }
}

/** How Caliper's normalized type `c` stands against the checker's `k`. */
export function compare(c: Norm, k: Norm, depth = 0): Verdict {
  if (depth > MAX_DEPTH) return 'identical'
  // The checker has no type to compare with: an error, `any`, or a top-level `unknown` where Caliper has a type
  // (most often a declaration the program couldn't resolve).
  const uninformative =
    k.k === 'error' || (k.k === 'prim' && k.name === 'any') || (depth === 0 && k.k === 'prim' && k.name === 'unknown')
  if (uninformative && !(c.k === 'prim' && k.k === 'prim' && c.name === k.name)) {
    return depth === 0 ? 'checker any/error' : 'identical'
  }
  const km = members(k)
  // An optional prop of type `never` reads `undefined` in the checker, which `members` drops as the optional marker.
  if (km.length === 0 && c.k === 'prim' && c.name === 'never') return 'identical'
  if (c.k === 'name') {
    // An optional prop's checker type is `X | undefined`; the name is X's.
    const target = km.length === 1 ? km[0] : k
    if ((target.alias && bareName(target.alias) === c.name) || (k.alias && bareName(k.alias) === c.name)) {
      return 'spelled'
    }
    if (target.k === 'param' && target.name === c.name) return 'identical'
    // A name Caliper left unexpanded where the checker has the type itself (an unbound parameter, an alias that
    // resolves to another name).
    return 'less precise'
  }
  if (k.k === 'opaque') return 'identical'
  if (c.k === 'opaque') return 'less precise'
  if (c.k === 'prim' && (c.name === 'any' || c.name === 'unknown') && !(k.k === 'prim' && k.name === c.name)) {
    return 'less precise'
  }
  // An intersection Caliper left as written, which the checker reduced (`Mode & …` to a literal union).
  if (c.k === 'intersection' && !km.some((m) => m.k === 'intersection')) return 'less precise'
  const cm = members(c, true)
  if (cm.length !== 1 || km.length !== 1) return compareUnions(cm, km, depth)
  const [cOne] = cm
  const [kOne] = km
  if (cOne !== c || kOne !== k) return compare(cOne, { ...kOne, alias: kOne.alias ?? k.alias }, depth)
  return compareOne(c, k, depth)
}

// react-docgen-typescript on one corpus (scripts/weekly.py): every component's props with their declaring file, plus
// RDT's own wall time and peak RSS. RDT comes from apps/oracle, with the options its harness uses.
//
// Usage: node scripts/rdt.mjs <file-list> <tsconfig> <out.json>
import { readFileSync, writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'

const require = createRequire(fileURLToPath(new URL('../apps/oracle/package.json', import.meta.url)))
const { withCustomConfig } = require('react-docgen-typescript')

const [listFile, tsconfig, out] = process.argv.slice(2)
if (!out) {
  console.error('usage: node scripts/rdt.mjs <file-list> <tsconfig> <out.json>')
  process.exit(2)
}
const files = readFileSync(listFile, 'utf8').split('\n').filter(Boolean)
const start = performance.now()
const parser = withCustomConfig(tsconfig, {
  shouldExtractLiteralValuesFromEnum: true,
  shouldRemoveUndefinedFromOptional: true,
  propFilter: { skipPropsWithoutDoc: false },
})
const docs = parser.parse(files)
const wallMs = performance.now() - start
const components = docs.map((d) => ({
  file: d.filePath,
  name: d.displayName,
  props: Object.fromEntries(
    Object.entries(d.props ?? {}).map(([k, p]) => [
      k,
      {
        required: Boolean(p.required),
        type: p.type?.name ?? '',
        parent: p.parent?.fileName ?? p.declarations?.[0]?.fileName ?? '',
      },
    ]),
  ),
}))
// `maxRSS` is in kilobytes on every platform Node supports.
const peakRssMiB = process.resourceUsage().maxRSS / 1024
writeFileSync(out, JSON.stringify({ wallMs, peakRssMiB, components }))
console.error(`dumped ${components.length} components in ${(wallMs / 1000).toFixed(1)} s, ${peakRssMiB.toFixed(0)} MiB`)

// react-docgen (what Storybook ships) on one corpus (scripts/weekly.py): every component's props, in the shape
// scripts/rdt.mjs writes, plus its own wall time and peak RSS. It reads each file on its own with its default
// resolver and importer, as Storybook does, so it knows nothing about types declared in other files.
//
// Usage: node scripts/rdg.mjs <file-list> <out.json>
import { readFileSync, writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { pathToFileURL, fileURLToPath } from 'node:url'

const require = createRequire(fileURLToPath(new URL('../apps/oracle/package.json', import.meta.url)))
const { parse } = await import(pathToFileURL(require.resolve('react-docgen')).href)

const [listFile, out] = process.argv.slice(2)
if (!out) {
  console.error('usage: node scripts/rdg.mjs <file-list> <out.json>')
  process.exit(2)
}
const files = readFileSync(listFile, 'utf8').split('\n').filter(Boolean)
const components = []
let failed = 0
const start = performance.now()
for (const file of files) {
  try {
    for (const doc of parse(readFileSync(file, 'utf8'), { filename: file })) {
      components.push({
        file,
        name: doc.displayName ?? '',
        props: Object.fromEntries(
          Object.entries(doc.props ?? {}).map(([k, p]) => [
            k,
            { required: Boolean(p.required), type: p.tsType?.raw ?? p.tsType?.name ?? '', parent: '' },
          ]),
        ),
      })
    }
  } catch {
    failed += 1
  }
}
const wallMs = performance.now() - start
// `maxRSS` is in kilobytes on every platform Node supports.
const peakRssMiB = process.resourceUsage().maxRSS / 1024
writeFileSync(out, JSON.stringify({ wallMs, peakRssMiB, failed, components }))
console.error(`${components.length} components from ${files.length} files (${failed} failed) in ${(wallMs / 1000).toFixed(1)} s`)

// TypeScript 7.1's checker as a test oracle for Caliper's prop types (docs/parity.md). Test-only: the opt-in semantic
// backend is a separate, experimental feature.
//
// For one corpus, finds components the way react-docgen-typescript does (an exported function whose only or `props`
// parameter is the props type), reads each prop's type from the checker, and compares it structurally with the prop
// Caliper's canonical JSON reports for the same component (src/oracle-compare.ts). Each shared prop gets one verdict:
//
//   identical          both sides describe the same type
//   spelled            the same type, Caliper by name where the checker expands it, or the reverse
//   less precise       Caliper's type is looser or unevaluated (an opaque type, `string` for a literal union, a name
//                      left unexpanded, a lost optional or rest parameter, a missing field)
//   wrong              Caliper's type describes something else
//   checker any/error  the checker itself has no type (an unresolved import, `any`, or `unknown` where Caliper has one)
//
// Checker types are normalized once per type id and verdicts made once per (Caliper prop, checker type), so Chakra's
// ~470,000 props cost a few thousand distinct comparisons.
//
import { readdirSync, readFileSync, realpathSync, writeFileSync } from 'node:fs'
import { join, relative } from 'node:path'
import { API, SignatureKind, SymbolFlags } from 'typescript-beta/sync'
import { checkerNormalizer } from './oracle-checker.ts'
import { caliperNorm, compare, VERDICTS, type Norm, type Verdict } from './oracle-compare.ts'

const KEYS = ['root', 'src', 'tsconfig', 'caliper', 'out', 'files', 'dump', 'rows', 'missing'] as const
const args: Partial<Record<(typeof KEYS)[number], string>> = {}
for (let i = 2; i < process.argv.length; i += 2) {
  args[process.argv[i].replace(/^--/, '') as (typeof KEYS)[number]] = process.argv[i + 1]
}
if (!args.root || !args.src || !args.tsconfig || !args.caliper || !args.out) {
  console.error('usage: tsx src/oracle.ts --root DIR --src DIR --tsconfig FILE --caliper FILE --out FILE')
  process.exit(2)
}
const root = realpathSync(args.root)

function walk(dir: string): string[] {
  const out: string[] = []
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.name === 'node_modules') continue
    const path = join(dir, entry.name)
    if (entry.isDirectory()) out.push(...walk(path))
    else out.push(path)
  }
  return out
}

const files: string[] = args.files
  ? readFileSync(args.files, 'utf8').split('\n').filter(Boolean)
  : walk(realpathSync(args.src))
      .filter((f) => f.endsWith('.tsx'))
      .toSorted()

const api = new API({ cwd: root })
const programStart = performance.now()
// The same program react-docgen-typescript parses in scripts/weekly.py: the component files, with the tsconfig it
// uses. The options go through `parseConfigFile` because the 7.1 beta's server panics on string-valued enum options
// passed to `createProgram` directly.
const { options } = api.parseConfigFile(args.tsconfig)
const program = api.createProgram(files, options)
const { checker } = program.getProject()
const programMs = performance.now() - programStart
const checkerNorm = checkerNormalizer(checker)

// ─── Components ───────────────────────────────────────────────────────────────

const normComponent = (name: string) =>
  (
    name
      .replace(/ \(.*\)$/, '')
      .split('/')
      .at(-1) ?? ''
  )
    .split('.')
    .at(-1)!
    .replaceAll(/[^A-Za-z0-9]/g, '')
const rel = (path: string) => relative(root, realpathSync(path))
const pathKey = (path: string) =>
  process.platform === 'darwin' || process.platform === 'win32' ? path.toLowerCase() : path

const caliper = JSON.parse(readFileSync(args.caliper, 'utf8'))
const caliperByFile = new Map<string, { name: string; key: string; component: any }[]>()
for (const [componentKey, component] of Object.entries<any>(caliper.components)) {
  // Schema 2 lists a component's prop set ids, each a map of prop name to prop id; this reads one map of both.
  if (Array.isArray(component.props)) {
    component.props = Object.assign({}, ...component.props.map((id: string) => caliper.propSets[id]))
  }
  const key = rel(component.filePath)
  const list = caliperByFile.get(key) ?? []
  list.push({ name: normComponent(component.displayName), key: componentKey, component })
  caliperByFile.set(key, list)
}

/** The props type of a component export, the way react-docgen-typescript finds it. */
function propsTypeOf(exported: any): any | undefined {
  const symbol = exported.flags & SymbolFlags.Alias ? checker.getAliasedSymbol(exported) : exported
  const type = checker.getTypeOfSymbol(symbol)
  for (const sig of checker.getSignaturesOfType(type, SignatureKind.Call)) {
    const params = sig.getParameters()
    if (params.length === 1 || params[0]?.name === 'props') return checker.getTypeOfSymbol(params[0])
  }
  for (const sig of checker.getSignaturesOfType(type, SignatureKind.Construct)) {
    if (sig.getParameters().length > 1) continue
    const props = checker.getPropertyOfType(sig.getReturnType(), 'props')
    if (props) return checker.getTypeOfSymbol(props)
  }
  return undefined
}

/** A default export is named by what it exports: the aliased declaration, or the function or class itself. */
function exportName(exported: any): string {
  if (exported.name !== 'default') return exported.name
  if (exported.flags & SymbolFlags.Alias) return checker.getAliasedSymbol(exported).name
  return checker.getTypeOfSymbol(exported).getSymbol()?.name ?? 'default'
}

interface Example {
  component: string
  prop: string
  caliper: unknown
  checker: string
  normalized: object
}
const counts = Object.fromEntries(VERDICTS.map((v) => [v, 0])) as Record<Verdict, number>
const examples = Object.fromEntries(VERDICTS.map((v) => [v, [] as Example[]])) as Record<Verdict, Example[]>
const verdictCache = new Map<string, Verdict>()
const rows: [string, string, Verdict | 'missing' | 'collapsed'][] = []
const missingDetails: { key: string; prop: string; verdict: 'missing' | 'collapsed'; declarations: string[] }[] = []
const dumped: {
  key: string
  file: string
  component: string
  prop: string
  verdict: Verdict
  caliper: unknown
  checker: string
}[] = []
const totals = {
  componentsChecker: 0,
  componentsMatched: 0,
  propsChecker: 0,
  propsShared: 0,
  propsMissing: 0,
  propsCollapsed: 0,
  failedExports: 0,
  ambiguousExports: 0,
}

/** The verdict for one prop, made once per (Caliper prop, checker type). */
function judge({
  component,
  prop,
  caliperId,
  type,
}: {
  component: string
  prop: string
  caliperId: string
  type: any
}) {
  const key = `${caliperId}:${type.id}`
  const cached = verdictCache.get(key)
  if (cached !== undefined) return cached
  const c: Norm = caliperNorm(caliper.props[caliperId].type)
  const k: Norm = checkerNorm(type)
  const verdict = compare(c, k)
  verdictCache.set(key, verdict)
  if (examples[verdict].length < 20) {
    const checkerText = checker.typeToString(type)
    examples[verdict].push({
      component,
      prop,
      caliper: caliper.props[caliperId].type,
      checker: checkerText,
      normalized: { caliper: c, checker: k },
    })
  }
  return verdict
}

/** Every prop of one exported component the checker finds, against Caliper's component of the same name. */
function visitExport(exported: any, candidates: { name: string; key: string; component: any }[], file: string): void {
  let propsType
  try {
    propsType = propsTypeOf(exported)
  } catch {
    totals.failedExports++
    return
  }
  if (!propsType) return
  const props = checker.getPropertiesOfType(propsType)
  if (props.length === 0) return
  totals.componentsChecker++
  const name = exportName(exported)
  // React's DOM attributes are one inherited layer; ref and key are deliberately absent from Caliper's output.
  const own = props.filter(
    (p: any) =>
      p.name !== 'ref' &&
      p.name !== 'key' &&
      !p.declarations?.some((d: any) => String(d.path).includes('/@types/react/')),
  )
  totals.propsChecker += own.length
  const matches = candidates.filter((c) => c.name === normComponent(name))
  if (matches.length > 1) {
    totals.ambiguousExports++
    return
  }
  const [match] = matches
  if (!match) return
  totals.componentsMatched++
  const shared = own.filter((p: any) => p.name in match.component.props)
  const layerFiles = new Set(
    (match.component.inheritance ?? [])
      .filter((layer: any) => layer.totalProps > 30)
      .map((layer: any) => pathKey(String(layer.fileName))),
  )
  const absent = own.filter((p: any) => !(p.name in match.component.props))
  const collapsed: any[] = []
  const missing: any[] = []
  for (const p of absent) {
    if (p.declarations?.some((d: any) => layerFiles.has(pathKey(String(d.path))))) collapsed.push(p)
    else missing.push(p)
  }
  totals.propsMissing += missing.length
  totals.propsCollapsed += collapsed.length
  if (args.rows) rows.push(...missing.map((p: any) => [match.key, p.name, 'missing'] as [string, string, 'missing']))
  if (args.rows)
    rows.push(...collapsed.map((p: any) => [match.key, p.name, 'collapsed'] as [string, string, 'collapsed']))
  if (args.missing) {
    for (const [verdict, absentProps] of [
      ['missing', missing],
      ['collapsed', collapsed],
    ] as const) {
      for (const p of absentProps) {
        missingDetails.push({
          key: match.key,
          prop: p.name,
          verdict,
          declarations: p.declarations?.map((d: any) => String(d.path)) ?? [],
        })
      }
    }
  }
  if (shared.length === 0) return
  const types = checker.getTypeOfSymbol(shared)
  for (const [i, p] of shared.entries()) {
    totals.propsShared++
    const caliperId = match.component.props[p.name]
    const verdict = judge({ component: name, prop: p.name, caliperId, type: types[i] })
    counts[verdict]++
    if (args.rows) rows.push([match.key, p.name, verdict])
    if (args.dump && (verdict === 'wrong' || verdict === 'less precise')) {
      dumped.push({
        key: match.key,
        file: rel(file),
        component: name,
        prop: p.name,
        verdict,
        caliper: caliper.props[caliperId].type,
        checker: checker.typeToString(types[i]),
      })
    }
  }
}

const start = performance.now()
for (const file of files) {
  const moduleSymbol = checker.getSymbolOfSourceFile(file)
  if (!moduleSymbol) continue
  const candidates = caliperByFile.get(rel(file)) ?? []
  for (const exported of checker.getExportsOfModule(moduleSymbol)) visitExport(exported, candidates, file)
}
const compareMs = performance.now() - start

const report = {
  components_checker: totals.componentsChecker,
  components_matched: totals.componentsMatched,
  props_checker: totals.propsChecker,
  props_shared: totals.propsShared,
  props_missing: totals.propsMissing,
  props_collapsed: totals.propsCollapsed,
  verdicts: counts,
  distinct_comparisons: verdictCache.size,
  failed_exports: totals.failedExports,
  ambiguous_exports: totals.ambiguousExports,
  program_ms: Math.round(programMs),
  compare_ms: Math.round(compareMs),
  examples,
}
writeFileSync(args.out, JSON.stringify(report, null, 2))
if (args.dump) writeFileSync(args.dump, JSON.stringify(dumped))
if (args.rows) writeFileSync(args.rows, JSON.stringify(rows))
if (args.missing) writeFileSync(args.missing, JSON.stringify(missingDetails))
program.dispose()
api.close()
console.error(
  `${totals.componentsMatched}/${totals.componentsChecker} components, ${totals.propsShared} shared props, ` +
    `${verdictCache.size} distinct comparisons, program ${(programMs / 1000).toFixed(1)} s, ` +
    `compare ${(compareMs / 1000).toFixed(1)} s`,
)

// The oracle's comparison is pure, so its verdicts are tested without a checker.
import { describe, expect, it } from 'vitest'
import { compare, prim, type Norm } from '../src/oracle-compare.ts'

const lit = (value: string): Norm => ({ k: 'lit', value })
const union = (...members: Norm[]): Norm => ({ k: 'union', members })
const undef = prim('undefined')
const optional = (type: Norm): Norm => union(type, undef)

describe('the oracle comparison', () => {
  it('a type parameter Caliper replaced with its default is one instance of it, not another type', () => {
    expect.hasAssertions()
    // `multiple?: Multiple` with `Multiple extends boolean = false`, which Caliper reads as `false`.
    const multiple: Norm = { k: 'param', name: 'Multiple', fallback: lit('false'), constraint: prim('boolean') }
    expect(compare(lit('false'), optional(multiple))).toBe('less precise')
    expect(compare(prim('boolean'), optional(multiple))).toBe('less precise')
  })

  it('a parameter with neither a default nor a constraint holds whatever instance Caliper picked', () => {
    expect.hasAssertions()
    // antd's `Segmented`: `defaultValue?: ValueType` where the cast over `forwardRef` declares `<ValueType>` bare and
    // the props interface declares the default Caliper used.
    const valueType: Norm = { k: 'param', name: 'ValueType' }
    expect(compare(union(prim('string'), prim('number')), optional(valueType))).toBe('less precise')
  })

  it('a literal a primitive of its kind in the same union covers adds nothing', () => {
    expect.hasAssertions()
    // antd's `DrawerPanel`: `size?: 'default' | 'large' | number | string`, which the checker reduces to `string | number`.
    const written = union(lit('default'), lit('large'), prim('number'), prim('string'))
    expect(compare(written, optional(union(prim('string'), prim('number'))))).toBe('identical')
    // Without the primitive the literals are still the type.
    expect(compare(union(lit('default'), lit('large')), optional(union(lit('default'), lit('large'))))).toBe(
      'identical',
    )
    // A numeric literal is covered by `number`, not by `string`.
    expect(compare(union(lit('1'), prim('string')), optional(union(lit('1'), prim('string'))))).toBe('identical')
  })

  it('a type parameter replaced with its constraint is one instance of it', () => {
    expect.hasAssertions()
    // `value?: Value` with `Value extends string`, which Caliper reads as `string`.
    const value: Norm = { k: 'param', name: 'Value', constraint: prim('string') }
    expect(compare(prim('string'), optional(value))).toBe('less precise')
  })

  it('a type that is neither the default nor the constraint of the parameter is wrong', () => {
    expect.hasAssertions()
    const value: Norm = { k: 'param', name: 'Value', fallback: prim('string'), constraint: prim('string') }
    expect(compare(prim('number'), optional(value))).toBe('wrong')
  })

  it('a union Caliper wrote out fits a parameter whose default is that union', () => {
    expect.hasAssertions()
    // `value?: ValueType` with `ValueType extends SegmentedValue = SegmentedValue`, and `SegmentedValue = string | number`.
    const both = union(prim('string'), prim('number'))
    const valueType: Norm = { k: 'param', name: 'ValueType', fallback: both, constraint: both }
    expect(compare(both, optional(valueType))).toBe('less precise')
    expect(compare(union(prim('string'), prim('boolean')), optional(valueType))).toBe('wrong')
  })

  it('a type parameter inside an array is compared through the same instances', () => {
    expect.hasAssertions()
    const value: Norm = { k: 'param', name: 'Value', constraint: prim('string') }
    const checker: Norm = { k: 'array', element: value }
    expect(compare({ k: 'array', element: prim('string') }, checker)).toBe('less precise')
    expect(compare({ k: 'array', element: prim('number') }, checker)).toBe('wrong')
  })

  it('an optional prop of type never is undefined in the checker', () => {
    expect.hasAssertions()
    // `classNames?: never` reads `undefined`, the optional marker the comparison drops.
    expect(compare(prim('never'), undef)).toBe('identical')
    expect(compare(prim('never'), prim('string'))).toBe('wrong')
    expect(compare(prim('string'), undef)).toBe('wrong')
  })
})

