2	// once per type id and depth.
3	import { SignatureKind, SymbolFlags, TypeFlags } from 'typescript-beta/sync'
4	import { MAX_DEPTH, prim, type Norm } from './oracle-compare.ts'
5	
6	const ANONYMOUS = new Set(['__type', '__object', '__function', '__call', ''])
7	
8	const INTRINSICS: [number, string][] = [
9	  [TypeFlags.Any, 'any'],
10	  [TypeFlags.Unknown, 'unknown'],
11	  [TypeFlags.String, 'string'],
12	  [TypeFlags.Number, 'number'],
13	  [TypeFlags.BigInt, 'bigint'],
14	  [TypeFlags.ESSymbol, 'symbol'],
15	  [TypeFlags.Null, 'null'],
16	  [TypeFlags.Undefined, 'undefined'],
17	  [TypeFlags.Void, 'void'],
18	  [TypeFlags.Never, 'never'],
19	  [TypeFlags.NonPrimitive, 'object'],
20	  // A pattern such as `var(--${string})` or `Uppercase<string>` stands for strings.
21	  [TypeFlags.TemplateLiteral | TypeFlags.StringMapping, 'string'],
22	]
23	
24	/** The checker's name for a type: its alias, or the interface, class or enum that declares it. */
25	function typeName(t: any): string | undefined {
26	  const alias = t.getAliasSymbol()
27	  if (alias && !ANONYMOUS.has(alias.name)) return alias.name
28	  if (t.flags & (TypeFlags.Object | TypeFlags.Enum | TypeFlags.EnumLiteral)) {
29	    const symbol = t.getSymbol()
30	    if (symbol && !ANONYMOUS.has(symbol.name)) return symbol.name
31	  }
32	  return undefined
33	}
34	
35	/** A normalizer bound to one checker, caching by type id and depth. */
36	export function checkerNormalizer(checker: any): (t: any) => Norm {
37	  const cache = new Map<string, Norm>()
38	
39	  function norm(t: any, depth = 0): Norm {
40	    const key = `${t.id}:${depth}`
41	    const cached = cache.get(key)
42	    if (cached) return cached
43	    const result = uncached(t, depth)
44	    cache.set(key, result)
45	    return result
46	  }
47	
48	  function scalar(t: any): Norm | undefined {
49	    const f: number = t.flags
50	    if (t.isErrorType()) return { k: 'error' }
51	    if (f & TypeFlags.Boolean) return { ...prim('boolean'), alias: typeName(t) }
52	    const intrinsic = INTRINSICS.find(([flag]) => f & flag)
53	    if (intrinsic) return prim(intrinsic[1])
54	    // The beta's responses carry neither `value` nor `intrinsicName` for `true` and `false`.
55	    if (f & TypeFlags.BooleanLiteral) return { k: 'lit', value: checker.typeToString(t) }
56	    if (f & (TypeFlags.StringLiteral | TypeFlags.NumberLiteral | TypeFlags.BigIntLiteral)) {
57	      return { k: 'lit', value: String(t.value) }
58	    }
59	    return undefined
60	  }
61	
62	  /** A type parameter with what Caliper may have put in its place: its default, and its constraint. */
63	  const expanding = new Set<number>()
64	  function typeParameter(t: any, depth: number): Norm {
65	    const name: string = t.getSymbol()?.name ?? ''
66	    // A parameter inside its own default or constraint (`T extends Foo<T>`) is its name.
67	    if (expanding.has(t.id)) return { k: 'param', name }
68	    expanding.add(t.id)
69	    // Its instances sit one level down, but never past the depth limit, where a scalar one still reads.
70	    const at = Math.min(depth + 1, MAX_DEPTH)
71	    const read = (get: () => any): Norm | undefined => {
72	      try {
73	        const type = get()
74	        return type ? norm(type, at) : undefined
75	      } catch {
76	        return undefined
77	      }
78	    }
79	    try {
80	      return {
81	        k: 'param',
82	        name,
83	        fallback: read(() => checker.getDefaultFromTypeParameter(t)),
84	        constraint: read(() => checker.getBaseConstraintOfType(t)),
85	      }
86	    } finally {
87	      expanding.delete(t.id)
88	    }
89	  }
