  const param = (type: Norm, marks: { optional?: boolean; rest?: boolean } = {}) => ({
    optional: false,
    rest: false,
    ...marks,
    type,
  })
  const fn = (...params: ReturnType<typeof param>[]): Norm => ({ k: 'function', params, returns: prim('void') })

