    expect.hasAssertions()
    const optional = fn(param(prim('string'), { optional: true }))
    const rest = fn(param(prim('string'), { rest: true }))
    expect(compare(optional, optional)).toBe('identical')
    expect(compare(rest, rest)).toBe('identical')
